public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0]] = true;
    queue.add(start[0]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection from the queue
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end[0]) {
            return "can be travelled";
        }

        // Loop through all the paths from the current n-tersection
        for (int i = 0; i < paths.length; i++) {
            // If the path is not visited and leads to a new n-tersection, mark it as visited and add it to the queue
            if (!visited[paths[i][0]] && paths[i][1] == current) {
                visited[paths[i][0]] = true;
                queue.add(paths[i][0]);
            }
        }
    }

    // If the queue is empty and the ending n-tersection was not reached, return "cannot be travelled"
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int denominator = word1.length() + word2.length();
    if (denominator == 0) {
        return "0";
    }
    int numerator = commonLetters;
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

