public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    if (x1 == x2 && y1 == y2) {
        return false;
    }
    if (x2 == x3 && y2 == y3) {
        return false;
    }
    if (x1 == x3 && y1 == y3) {
        return false;
    }

    int slope1 = (y2 - y1) / (x2 - x1);
    int slope2 = (y3 - y2) / (x3 - x2);

    if (slope1 == slope2) {
        return false;
    }

    int intercept1 = y1 - (slope1 * x1);
    int intercept2 = y2 - (slope2 * x2);

    if (intercept1 == intercept2) {
        return false;
    }

    return true;
}

