public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
        int squares = 0;
        int current = i;
        while (current > 0) {
            int root = (int) Math.sqrt(current);
            squares++;
            current = current - root * root;
        }
        minSquares = Math.min(minSquares, squares);
    }
    return minSquares;
}

